let assignmentLinks=[['meera','cs203'],['anil','cs211'],['meera','cs220'],['anil','cs208']],selectedFacultyNode='',stagedAssignmentChanges=[];
function effectiveAssignmentLinks(){return [...assignmentLinks.filter(([f,c])=>!stagedAssignmentChanges.some(x=>x.type==='remove'&&x.faculty===f&&x.course===c)),...stagedAssignmentChanges.filter(x=>x.type==='add').map(x=>[x.faculty,x.course])]}
function renderAssignmentLabels(){document.querySelectorAll('[data-assignees]').forEach(box=>{const course=box.dataset.assignees,links=effectiveAssignmentLinks().filter(x=>x[1]===course);box.innerHTML=links.length?links.map(([faculty])=>`<span class="assignee-chip ${stagedAssignmentChanges.some(x=>x.type==='add'&&x.faculty===faculty&&x.course===course)?'pending-add':''}">${facultyById[faculty].name}<button data-remove="${course}|${faculty}" aria-label="Stage removal">×</button></span>`).join(''):'<span class="unassigned-label">⚠ No faculty assigned</span>'})}
function drawAssignmentEdges(){const stage=$('#graphStage'),svg=$('#assignmentEdges');if(!stage||!svg)return;const rect=stage.getBoundingClientRect();svg.setAttribute('width',stage.clientWidth);svg.setAttribute('height',stage.clientHeight);svg.innerHTML='';for(const [f,c] of effectiveAssignmentLinks()){const from=stage.querySelector(`[data-source="${f}"]`),to=stage.querySelector(`[data-target="${c}"]`);if(!from||!to||from.closest('[hidden]')||to.closest('[hidden]'))continue;const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),x1=a.left+a.width/2-rect.left,y1=a.top+a.height/2-rect.top,x2=b.left+b.width/2-rect.left,y2=b.top+b.height/2-rect.top,curve=Math.max(55,(x2-x1)*.48),path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M ${x1} ${y1} C ${x1+curve} ${y1}, ${x2-curve} ${y2}, ${x2} ${y2}`);path.setAttribute('class',stagedAssignmentChanges.some(x=>x.type==='add'&&x.faculty===f&&x.course===c)?'edge staged-edge':'edge');svg.append(path)}const assigned=new Set(effectiveAssignmentLinks().map(x=>x[1])).size;$('#assignedCount').textContent=String(assigned);$('#unassignedCount').textContent=String(Math.max(0,5-assigned));$('#stagedCount').textContent=String(stagedAssignmentChanges.length);$('#stagedToolbar').hidden=stagedAssignmentChanges.length===0}
function stageFacultyLink(faculty,course){if(!faculty||!course)return;stagedAssignmentChanges=stagedAssignmentChanges.filter(x=>!(x.course===course&&x.type==='add'));stagedAssignmentChanges=stagedAssignmentChanges.filter(x=>!(x.faculty===faculty&&x.course===course&&x.type==='remove'));if(!assignmentLinks.some(x=>x[0]===faculty&&x[1]===course))stagedAssignmentChanges.push({type:'add',faculty,course});selectedFacultyNode='';document.querySelectorAll('.faculty-node.selected-node').forEach(n=>n.classList.remove('selected-node'));document.querySelector(`[data-course="${course}"]`)?.classList.add('staged-node');renderAssignmentLabels();drawAssignmentEdges()}
function initAssignmentCanvas(){if(active!=='assignments'||roleKey!=='hod')return;stagedAssignmentChanges=[];selectedFacultyNode='';renderAssignmentLabels();drawAssignmentEdges();$('#graphStage')?.addEventListener('dragover',e=>{if(e.target.closest('.course-node'))e.preventDefault()});$('#graphStage')?.addEventListener('drop',e=>{const course=e.target.closest('.course-node');if(!course)return;e.preventDefault();const faculty=e.dataTransfer.getData('text/faculty');if(faculty)stageFacultyLink(faculty,course.dataset.course)});$('#graphStage')?.addEventListener('dragstart',e=>{const node=e.target.closest('.faculty-node');if(!node)return;e.dataTransfer.setData('text/faculty',node.dataset.faculty);e.dataTransfer.effectAllowed='link'});$('#graphStage')?.addEventListener('click',e=>{const remove=e.target.closest('[data-remove]');if(remove){const [course,faculty]=remove.dataset.remove.split('|');stagedAssignmentChanges.push({type:'remove',faculty,course});remove.closest('.assignee-chip').classList.add('pending-remove');renderAssignmentLabels();drawAssignmentEdges();return}const faculty=e.target.closest('.faculty-node');if(faculty){selectedFacultyNode=faculty.dataset.faculty;document.querySelectorAll('.faculty-node').forEach(n=>n.classList.toggle('selected-node',n===faculty));return}const course=e.target.closest('.course-node');if(course&&selectedFacultyNode)stageFacultyLink(selectedFacultyNode,course.dataset.course)});$('#assignmentSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.faculty-node').forEach(n=>n.hidden=!n.textContent.toLowerCase().includes(q));document.querySelectorAll('.course-node').forEach(n=>n.hidden=!n.textContent.toLowerCase().includes(q));drawAssignmentEdges()});$('#assignmentSemester')?.addEventListener('change',e=>{document.querySelectorAll('.course-node').forEach(n=>n.hidden=e.target.value!=='all'&&n.dataset.semester!==e.target.value);drawAssignmentEdges()});document.querySelectorAll('.touch-course-card select').forEach((select,i)=>select.addEventListener('change',()=>{const course=['cs203','cs211','cs220','cs208','cs315'][i],faculty=Object.keys(facultyById).find(id=>facultyById[id].name===select.value);if(faculty)stageFacultyLink(faculty,course)}));requestAnimationFrame(drawAssignmentEdges)}
function commitAssignmentChanges(){for(const change of stagedAssignmentChanges){if(change.type==='remove')assignmentLinks=assignmentLinks.filter(x=>!(x[0]===change.faculty&&x[1]===change.course));if(change.type==='add'&&!assignmentLinks.some(x=>x[0]===change.faculty&&x[1]===change.course))assignmentLinks.push([change.faculty,change.course])}stagedAssignmentChanges=[];render()}
