function beginSignIn(key){pendingRole=key;$('#loginEmail').value=demoAccounts.find(x=>x[0]===key)[3];$('#loginPassword').value='Demo@2026';$('#loginPassword').type='password';$('#togglePassword').textContent='Show';$('#togglePassword').setAttribute('aria-label','Show password');$('#acceptTerms').checked=true;$('#loginError').hidden=true;continueSignIn()}
$('#demoAccounts').addEventListener('click',e=>{const account=e.target.closest('[data-demo-role]');if(account)beginSignIn(account.dataset.demoRole)});
function enterWorkspace(key){roleKey=key;active=roleHome[key];$('#loginScreen').hidden=true;$('#consentScreen').hidden=true;app.classList.add('authenticated');render()}
function continueSignIn(){const email=$('#loginEmail').value.trim().toLowerCase();const account=demoAccounts.find(x=>x[3]===email);if(!account||$('#loginPassword').value!=='Demo@2026'||!$('#acceptTerms').checked){$('#loginError').textContent=!$('#acceptTerms').checked?'Please accept the Terms of Use and Privacy Policy to sign in.':'Use one of the sample accounts and its demo password to continue.';$('#loginError').hidden=false;return}pendingRole=account[0];if(consentedRoles.has(pendingRole)){enterWorkspace(pendingRole);return}$('#consentIdentity').textContent=`Signed in as ${account[1]} Â· ${account[2]}`;$('#loginScreen').hidden=true;$('#consentScreen').hidden=false;$('#acceptConsent').checked=false;$('#acceptConsentButton').disabled=true}
$('#loginForm').addEventListener('submit',e=>{e.preventDefault();continueSignIn()});
$('#acceptConsent').addEventListener('change',e=>$('#acceptConsentButton').disabled=!e.target.checked);
$('#acceptConsentButton').addEventListener('click',()=>{if(!$('#acceptConsent').checked)return;consentedRoles.add(pendingRole);enterWorkspace(pendingRole)});
$('#backToLogin').addEventListener('click',()=>{$('#consentScreen').hidden=true;$('#loginScreen').hidden=false});
$('#togglePassword').addEventListener('click',()=>{const input=$('#loginPassword');const showing=input.type==='password';input.type=showing?'text':'password';$('#togglePassword').textContent=showing?'Hide':'Show';$('#togglePassword').setAttribute('aria-label',showing?'Hide password':'Show password');$('#togglePassword').setAttribute('aria-pressed',String(showing));input.focus()});
$('#forgotPassword').addEventListener('click',()=>{$('#loginError').textContent='Password reset preview: use a sample demo account above to continue.';$('#loginError').hidden=false});
document.addEventListener('click',e=>{const link=e.target.closest('[data-auth-message]');if(link){e.preventDefault();$('#loginError').textContent=`${link.dataset.authMessage} is represented as sample content in this UI preview.`;$('#loginError').hidden=false}});
document.addEventListener('click',e=>{const more=e.target.closest('#moreNavButton');if(more){const menu=$('#moreNavMenu');menu.hidden=!menu.hidden;return}const dayFilter=e.target.closest('[data-day-filter]');if(dayFilter){document.querySelectorAll('[data-day-filter]').forEach(b=>b.classList.toggle('active',b===dayFilter));document.querySelectorAll('[data-day-row]').forEach(row=>row.hidden=dayFilter.dataset.dayFilter!=='all'&&row.dataset.dayRow!==dayFilter.dataset.dayFilter);return}const page=e.target.closest('[data-page]');if(page){active=page.dataset.page;render();return}const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action;if(a==='saveAssignments'){commitAssignmentChanges();showToast('Faculty assignments saved in this preview');return}else if(a==='discardAssignments'){discardAssignmentChanges();return}else if(a==='day')showToast('Day view selected');else if(a==='refresh')showToast('Sample HOD data refreshed');else if(a==='export')showToast('Sample Excel export prepared');else if(a==='submit'||a==='generate'||a==='signin'||a==='promote'||a==='allocate'||a==='unlock'||a==='delete'||a==='add'||a==='edit'||a==='assign'||a==='upload'||a==='remind'||a==='view'||a==='save'||a==='pause'||a==='copy'||a==='download'||a==='export'||a==='refresh'||a==='addTeacher'||a==='manageTeachers'||a==='refreshAssignments')openModal(a,action.dataset);else showToast(({attendance:'Attendance roster opened in sample mode',download:'Sample template is ready',remind:'Reminder preview created',copy:'Sample student list copied',pause:'Window setting preview opened',studyhub:'Study Hub link preview'})[a]||'Sample action complete');return}if(e.target.closest('#noticeButton')){if(roleKey==='student'){active='notifications';render()}else showToast('No new notifications in this workspace')}});
$('#modalClose').addEventListener('click',closeModal);$('#modalCancel').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});$('#modalConfirm').addEventListener('click',()=>{const a=$('#modalConfirm').dataset.action;closeModal();if(a==='logout'){signOut();return}showToast(({signin:'Campus sign-in recorded in this preview',promote:'Promotion preview complete',unlock:'Late-entry unlock staged in this preview',delete:'Removal confirmation recorded in this preview',submit:'Course registration saved as a draft',generate:'Timetable draft generated',allocate:'Allocation preview complete',remind:'Reminder preview prepared'})[a]||'Saved in this preview')});
$('#profileButton').addEventListener('click',()=>openModal('logout'));
document.addEventListener('change',e=>{const select=e.target;if(!select.matches('[id^=hod]'))return;const value=select.value,container=$('#content');if(select.id==='hodBlueprintSemester'){const label=$('#hodBlueprintLabel');if(label)label.textContent=`Semester ${value} blueprint`;return}const selector=select.id==='hodDefaulterSemester'?'.hod-defaulter-row':select.id==='hodStudentsSemester'?'.hod-student-row':select.id==='hodCoursesSemester'?'.hod-course-row':select.id==='hodPeriodSemester'||select.id==='hodPeriodDay'?'.hod-period-row':select.id==='hodCampusSemester'?'.hod-campus-row':null;if(selector){const rows=[...container.querySelectorAll(selector)];rows.forEach(cell=>{const tr=cell.closest('tr');if(!tr)return;let hide=value!=='all'&&cell.dataset.semester!==value;if(cell.classList.contains('hod-period-row')){const sem=$('#hodPeriodSemester')?.value||'all',day=$('#hodPeriodDay')?.value||'all';hide=(sem!=='all'&&cell.dataset.semester!==sem)||(day!=='all'&&cell.dataset.day!==day)}tr.hidden=hide});if(select.id==='hodDefaulterSemester'){const visible=rows.filter(cell=>value==='all'||cell.dataset.semester===value),submitted=visible.filter(cell=>cell.dataset.submitted==='true').length;$('#hodDefTotal').textContent=String(visible.length);$('#hodDefSubmitted').textContent=String(submitted);$('#hodDefPending').textContent=String(visible.length-submitted)}}if(select.id==='hodCoursesSemester'){const title=$('#hodCoursesTitle');if(title)title.textContent=`Courses — Semester ${value}`}});document.addEventListener('change',e=>{if(e.target.id==='hodAllocationSemester'){document.querySelectorAll('.hod-allocation-row').forEach(row=>row.hidden=row.dataset.semester!==e.target.value)}});document.addEventListener('input',e=>{if(e.target.matches('.table-search')){const q=e.target.value.toLowerCase(),scope=e.target.closest('.panel')||$('#content');scope?.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}if(e.target===$('#globalSearch')&&e.target.value.length>1){const q=e.target.value.toLowerCase();const match=roles[roleKey].nav.find(n=>n[0].toLowerCase().includes(q));if(match){$('#crumbTitle').textContent=match[0];}}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch')?.focus()}if(e.key==='Escape'){closeModal();const menu=$('#hodQuickMenu'),point=$('#hodQuickPoint');if(menu&&!menu.hidden){menu.hidden=true;point?.setAttribute('aria-expanded','false')}}});
document.addEventListener('click',e=>{const root=$('#hodQuickControl');if(root&&roleKey==='hod'&&!root.contains(e.target)){const menu=$('#hodQuickMenu'),point=$('#hodQuickPoint');if(menu&&!menu.hidden){menu.hidden=true;point?.setAttribute('aria-expanded','false')}}});
const todayDate=$('#todayDate');if(todayDate)todayDate.textContent=new Intl.DateTimeFormat('en',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date());

document.addEventListener('click',e=>{const toggle=e.target.closest('#hodStudentPasswordToggle');if(!toggle)return;const input=document.querySelector('#hodNewStudentPassword');if(!input)return;const showing=input.type==='password';input.type=showing?'text':'password';toggle.textContent=showing?'Hide':'Show';toggle.setAttribute('aria-label',showing?'Hide password':'Show password');toggle.setAttribute('aria-pressed',String(showing));input.focus()});

document.querySelector("#modalConfirm").addEventListener("click",e=>{if(roleKey!=="hod"||active!=="students"||e.currentTarget.dataset.action!=="add")return;const invalid=[...document.querySelectorAll("#modalFields [required]")].find(input=>!input.checkValidity());if(invalid){e.stopImmediatePropagation();invalid.reportValidity()}},true);
document.addEventListener("click",e=>{const menu=document.querySelector("#moreNavMenu");if(menu&&!menu.hidden&&!e.target.closest("#moreNavButton")&&!e.target.closest("#moreNavMenu"))menu.hidden=true});
document.addEventListener("click",e=>{if(e.target.closest("#hodChooseRoster"))document.querySelector("#hodRosterFile")?.click();const toggle=e.target.closest("#hodBatchPasswordToggle");if(toggle){const input=document.querySelector("#hodBatchPassword");if(!input)return;const show=input.type==="password";input.type=show?"text":"password";toggle.textContent=show?"Hide":"Show"}});
document.addEventListener("change",e=>{if(e.target.id==="hodRosterFile"){const file=e.target.files?.[0];const label=document.querySelector("#hodRosterFileName");if(label)label.textContent=file?`${file.name} · ${(file.size/1024).toFixed(0)} KB`:"No file selected";document.querySelector("#hodUploadDropzone")?.classList.toggle("has-file",!!file)}if(e.target.id==="manualAllocationCourse")document.querySelector("#modalConfirm").disabled=!e.target.value});
document.addEventListener("dragover",e=>{if(e.target.closest("#hodUploadDropzone"))e.preventDefault()});
document.addEventListener("drop",e=>{const zone=e.target.closest("#hodUploadDropzone");if(!zone)return;e.preventDefault();const file=e.dataTransfer?.files?.[0];if(!file||!file.name.toLowerCase().endsWith(".csv")){showToast("Choose a CSV roster file");return}const input=zone.querySelector("#hodRosterFile");const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files;input.dispatchEvent(new Event("change",{bubbles:true}))});
document.querySelector("#modalConfirm").addEventListener("click",e=>{if(roleKey!=="hod"||active!=="allocation"||e.currentTarget.dataset.action!=="allocate")return;const input=document.querySelector("#manualAllocationCourse");if(input&&!input.value){e.stopImmediatePropagation();input.reportValidity()}},true);
document.addEventListener("dragenter",e=>{const zone=e.target.closest("#hodUploadDropzone");if(zone)zone.classList.add("drag-over")});document.addEventListener("dragleave",e=>{const zone=e.target.closest("#hodUploadDropzone");if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove("drag-over")});document.addEventListener("drop",e=>e.target.closest("#hodUploadDropzone")?.classList.remove("drag-over"));
document.addEventListener("click",e=>{const button=e.target.closest("[data-action=upload]");if(!button||roleKey!=="hod"||active!=="upload")return;e.stopImmediatePropagation();const file=document.querySelector("#hodRosterFile"),password=document.querySelector("#hodBatchPassword");if(!file?.files?.length){showToast("Choose a CSV roster file first");document.querySelector("#hodChooseRoster")?.focus();return}if(!password?.value||password.value.length<8){showToast("Enter a batch password with at least 8 characters");password?.focus();return}showToast("Roster upload preview is ready. Sample data only.")},true);
document.addEventListener("change",e=>{if(e.target.id==="hodPeriodSemester"||e.target.id==="hodPeriodDay")filterHodPeriodRows();if(e.target.id==="hodAllocationSemester"){const label=document.querySelector("#hodAllocationCourseSemester");if(label)label.textContent=e.target.value}});
document.addEventListener("input",e=>{if(e.target.id==="hodPeriodSlotSearch")filterHodPeriodRows();if(e.target.id==="hodPeriodRosterSearch"){const q=e.target.value.toLowerCase();e.target.closest(".panel")?.querySelectorAll("tbody tr").forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}});
function filterHodPeriodRows(){const semester=document.querySelector("#hodPeriodSemester")?.value||"all",day=document.querySelector("#hodPeriodDay")?.value||"all",query=(document.querySelector("#hodPeriodSlotSearch")?.value||"").toLowerCase();document.querySelectorAll(".hod-period-slot").forEach(row=>{row.hidden=(semester!=="all"&&row.dataset.semester!==semester)||(day!=="all"&&row.dataset.day!==day)||!row.textContent.toLowerCase().includes(query)})}
